import json,re
from pathlib import Path
R=Path(__file__).resolve().parents[2];E=R/'evidence/02'
files=[E/'notes.json',*sorted(E.glob('notes_extra*.json'))];ns={};owner={}
for f in files:
 for k,v in json.loads(f.read_text()).items():ns[k]=v;owner[k]=f
ns['eoe'].update(pages='1-8',problem='Zero-shot image out-of-distribution detection from known class names and pretrained CLIP. The supplied EOE paper is not a navigation or world-model method; the acronym must not be conflated with a navigation approach.',mechanism='Section 3 and Algorithm 1, pp. 3–4: prompt an LLM for outlier class names that are visually related but distinct from known classes. Far, near and fine-grained settings use different prompts. Remove lexical overlap, embed known and envisioned labels with CLIP, and compare them to the normalized image embedding. Equation 3 subtracts beta times the largest envisioned-outlier softmax probability from the largest known-class probability; the softmax denominator includes both sets and beta is 0.25. Threshold the resulting scalar for ID/OOD classification. Evaluation reports false positives at a threshold chosen to retain 95% of ID examples. There is no task-specific model training, dynamics model, action policy or future rollout. CLIP pretraining and offline LLM generation remain external dependencies.',novelty='Compared with MCM\'s closed set of known labels, ZOC\'s learned caption generator and CLIPN\'s extra encoder training, EOE uses prompted negative-label augmentation and an explicit outlier penalty. Semantic novelty detection does not establish calibrated navigation-action risk.',results='Table 1, p. 5 averages four ID datasets and four OOD datasets: FPR95 0.21/AUROC 99.92 versus MCM 2.68/99.40. CLIPN uses extra data and scores 0.67/99.80. Later results are substantially harder: the ImageNet far-OOD result on pp. 6–8 has FPR95 30.09/AUROC 92.96; near-OOD average is 9.07/98.59; the fine-grained average is 60.52/81.82 versus CLIPN 56.05/83.18. Thus near-perfect small-dataset numbers must not be generalized to all settings. These are paper experiments, not executed reproduction.',bottleneck='Generated negative labels cannot enumerate all unknown appearances. The ImageNet20 near-OOD setting filters semantic cosine overlap at 0.85, but this does not guarantee coverage of unseen categories or semantic disjointness elsewhere. LLM versions and prompts alter candidate lists. An unsafe or instruction-inconsistent navigation action may involve familiar objects, so transferring this score into action-risk estimation requires navigation-specific labels and tests.',followups='Use EOE only as adjacent semantic novelty-detection prior art. Its confidence-like score should be compared with, rather than equated to, transition uncertainty and navigation risk.')
ns['imaginenav'].update(problem='Open-vocabulary ObjectNav on HM3D/HSSD using a VLM without object-specific fine-tuning. The complete pipeline still contains trained waypoint and PointNav modules.',mechanism='Section 3: Where2Imagine uses ResNet18 and human ObjectNav demonstrations to predict displacement/orientation proposals. Six panoramic RGB directions and depth filter candidate views using wall-distance and rotation constraints. PolyOculus novel-view synthesis renders candidates; GPT-4o mini chooses an indexed image for the target object; pretrained VER PointNav executes and replans after arrival. Training includes Habitat-Web demonstrations. No persistent semantic map is maintained. The full system requires depth, despite introductory RGB-only descriptions.',novelty='The VLM chooses among predicted candidate views supported by learned waypoint proposals. This differs from prompting only on currently observed views.',results='Table 1, p. 7: HM3D SR 53/SPL 23.8 versus VLFM 52.5/30.4; HSSD 51/24.9. Oracle views raise SR to 62/59. Table 2, p. 8 compares learned versus fixed waypoints on 100 episodes: 56/24.3 versus 49/23.3. That smaller ablation differs from the 200-episode headline setting. Better success is not necessarily better path efficiency.',followups='ImagineNav++ (arXiv 2512.17435) adds selective foveation and memory: https://200203z.github.io/imaginenav-plus/ . Its recorded repository remains a forthcoming-code page. WMNav instead stores heuristic curiosity scores.')
ns['nwm'].update(mechanism='Section 3: a Stable Diffusion VAE encodes RGB images. CDiT processes target patches with self-attention and historical context with cross-attention; its interaction cost scales approximately as O(m n² d) for m context frames, n patches and width d, instead of self-attention over all concatenated frames. Four historical frames, displacement/yaw action and signed time offset up to 16 seconds condition adaptive layer normalization. Training uses clean-latent denoising MSE plus a variance variational-bound term. Actions are normalized by robot step size; actionless Ego4D data can supply temporal supervision. At inference CEM or reranking uses generated endpoint similarity to a goal image. The largest 1B-parameter training uses 64 H100 GPUs and batch 4096. The inspected released CEM planner restricts candidate trajectories more than an unconstrained sequence optimizer; see code audit.',novelty='Cross-context diffusion with action/time conditioning supports flexible generative horizons and goal-image planning. It generates pixels, unlike DINO-WM\'s feature-only planner, and uses substantially larger visual priors/data than PlaNet without learning a task reward.',results='Table 1, p. 6: LPIPS is 0.760 with time only, 0.318 with action only and 0.295 with both. Table 2, p. 7: RECON two-second ATE/RPE is 1.13/0.35 versus NoMaD 1.93/0.52; reranking 32 proposals gives 1.78/0.48. These are offline trajectory errors, not measured physical success or collision guarantees.',followups='Vid2World adapts pretrained video generators to causal action conditioning; LCVN adds language, actor–critic learning and unified prediction. Their datasets and evaluation protocols differ.')
ns['sali']['mechanism']='Sections 3.1–3.3, pp. 3–5: graph memory distinguishes visited/current, reachable-candidate and imagined locations. Features, positions and temporal markers feed separate real/imagined node encoders and instruction-conditioned graph attention. Imagined scores are gated and added to the nearest reachable candidates (Eqs. 3–4). A recurrent imagination tree projects historical depth/semantics into future poses, completes missing structure, adjusts semantics using a room/object dictionary, synthesizes RGB with SPADE and predicts additional waypoints. The tree is merged into persistent memory; cosine similarity minus positional MSE controls capping/pruning (Eq. 1). Separate pretraining uses semantic cross-entropy, depth L1, room-type cross-entropy, GAN/perceptual/feature-matching losses and waypoint heatmap MSE. Navigation pretraining uses masked language, region, action and object-grounding tasks before encoder fine-tuning. The authors report 100,000 pretraining iterations at batch 32 and 20,000 fine-tuning iterations at batch four, using one then four Quadro RTX 8000 GPUs. Inference repeatedly updates the hybrid graph and selects a reachable or stop action.'
ns['sali']['results']+=' Table 2 on p. 7 reports full-system ablation SPL of 70/71 (SR 80/82), whereas the main R2R headline gives SPL 78. These configurations cannot be silently treated as the same experiment; the source does not permit a complete reconciliation.'
ns['sali']['bottleneck']=ns['sali']['bottleneck'].replace('pixelcost','pixel-generation cost')
replacements={'usingVLMwithout':'using a VLM without','andAlgorithm':'and Algorithm','anLLM':'an LLM','withCLIP':'with CLIP','aVLNexplorationmethod':'a VLN exploration method','adjacentsemanticOOD':'adjacent semantic OOD','reportsR2R':'reports R2R','unseenSR':'unseen SR ','ScaleVLN':'ScaleVLN','reportsFPR':'reports FPR','allOOD':'all OOD','stringsynonym':'string/synonym','promptdependent':'prompt-dependent','objectlabelspace':'object-label space','intoVLNrisk':'into VLN risk','pretrainedCLIP':'pretrained CLIP','plusAPIG':'plus APIG','usesMLM':'uses MLM','objectgrounding':'object grounding','featurematching':'feature matching','waypointheatmapMSE':'waypoint heatmap MSE','kpretrain':'k pretraining','kfinetune':'k fine-tuning','fourQuadroRTX':'four Quadro RTX','HAMTunseen':'HAMT unseen ','DUETtest':'DUET test ','HAMTtest':'HAMT test ','DUETunseen':'DUET unseen ','dynamic1000':'dynamic 1000','wholeimage':'whole-image','pretrainedvideo':'pretrained video','semanticCE':'semantic CE','depthL1':'depth L1','soft-targetCE':'soft-target CE','lossMSE':'loss MSE','GA N':'GAN','EMAfrequency':'EMA frequency','featureMSE':'feature MSE','Trainclean':'Train clean','TableI':'Table I','TableII':'Table II','TableIII':'Table III','panoRGB':'panoramic RGB','SR58':'SR 58','belowVLFM':'below VLFM','addingTAP':'adding TAP','versusGemini':'versus Gemini','PlanVLM':'PlanVLM','PredictVLM':'PredictVLM','ReasonVLM':'ReasonVLM','target/reward':'target/reward','pretrainedDINO':'pretrained DINO','FrozenDINO':'Frozen DINO','GroundingDINO':'Grounding DINO','latentGaussian':'latent Gaussian','predictedGaussian':'predicted Gaussian','taskrewards':'task rewards','targetmean':'target mean','FullR2R':'Full R2R','FullMP3D':'Full MP3D','fullSR':'full SR','Gibson91':'Gibson 91','frozenRoBERTa':'frozen RoBERTa','languagepriors':'language priors','gaussianmodel':'Gaussian model','VPRL':'VPRL','visualSFT':'visual SFT','QwenSFT':'Qwen SFT','withinLVM':'within LVM','forVPRL':'for VPRL','withinR2R':'within R2R','SSIM/LPIPS':'SSIM/LPIPS','selfsupervised':'self-supervised','mframes':'m frames','encodingMSE':'encoding MSE','largescale':'large-scale','taskreward':'task reward','butSSIM':'but SSIM','RT1FVD':'RT1 FVD ','Vid2WorldFVD':'Vid2World FVD ','versusmasked':'versus masked','versus action-conditioned24':'versus action-conditioned 24','GaussianSplat':'Gaussian Splat','VLM0':'VLM 0','WoMAPreal':'WoMAP real ','underlighting':'under lighting','oursSR':'ours SR','dthres':'d_thres','forstop':'for stop','subtask/current':'subtask/current','threeVLM':'three VLM','ThreeVLM':'Three VLM','Selectmaximum':'Select maximum','VLMproposal':'VLM proposal','LXMERT-style':'LXMERT-style','pixelBCE':'pixel BCE','semanticIoU':'semantic IoU','DynamiCrafter1':'DynamiCrafter 1','PlayStation':'PlayStation','trainingRGB':'training RGB','priormean':'prior mean','codebookγ':'codebook gamma','GAN hinge':'GAN hinge','H100s':'H100 GPUs','scaleimprovement':'scale improvement','DINOv2':'DINOv2','smallMLP':'small MLP','defaultSPL':'default SPL','seenSR':'seen SR ','taskbaseline':'task baseline','all68':'all 68','mean+alpha':'mean + alpha','autoregressivevisual':'autoregressive visual','noSCL':'no SCL','over1':'over 1','noonline':'no online','paperSPL':'paper SPL','final-stage':'final-stage'}
for n in ns.values():
 for key in ['problem','mechanism','novelty','results','bottleneck','followups','access']:
  if key not in n:continue
  s=n[key]
  for a,b in replacements.items():s=s.replace(a,b)
  for a,b in [('Vid 2 World','Vid2World'),('Where 2 Imagine','Where2Imagine'),('ImageNet 20','ImageNet20'),('Ego 4 D','Ego4D'),('GPT4omini','GPT-4o mini'),('PolyOculusNVS','PolyOculus NVS'),('32-channel','32-channel'),('100 k','100k')]:s=s.replace(a,b)
  s=re.sub(r'\b(Section|Table|Figure|Fig\.|Eq\.)\s*(\d)',r'\1 \2',s)
  s=re.sub(r'\b(SR|SPL|OSR|RGS|RGSPL|FVD|FID|ATE|RPE|LPIPS)(?=[\d.])',r'\1 ',s)
  s=re.sub(r'\b(vs|versus)(?=[A-Z\d])',r'\1 ',s)
  s=s.replace('pp.','pp. ').replace('p.','p. ') if not 'http' in s else s
  s=re.sub(r' +',' ',s)
  n[key]=s
for f in files:f.write_text(json.dumps({k:v for k,v in ns.items() if owner[k]==f},ensure_ascii=False,indent=2),encoding='utf-8')
print('Readability and evidence corrections written')
